CREATE OR REPLACE FUNCTION public.emit_webhook_event(_id text,_org uuid,_integration uuid,_environment public.environment,_type text,_body text,_endpoint uuid DEFAULT NULL,_company uuid DEFAULT NULL) RETURNS integer LANGUAGE plpgsql SET search_path=public AS $$ DECLARE n integer; BEGIN
PERFORM 1 FROM public.integrations WHERE id=_integration AND organization_id=_org AND active FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Integração inativa'; END IF;
IF _body::jsonb->>'id' IS DISTINCT FROM _id OR _body::jsonb->>'organizacao_id' IS DISTINCT FROM _org::text OR _body::jsonb->>'integracao_id' IS DISTINCT FROM _integration::text OR _body::jsonb->>'tipo' IS DISTINCT FROM _type OR _body::jsonb->>'ambiente' IS DISTINCT FROM (CASE WHEN _environment='sandbox' THEN 'homologacao' ELSE 'producao' END) THEN RAISE EXCEPTION 'Evento inválido'; END IF;
INSERT INTO public.webhook_events(id,organization_id,integration_id,environment,type,payload,body) VALUES(_id,_org,_integration,_environment,_type,_body::jsonb,_body);
INSERT INTO public.webhook_deliveries(id,event_id,endpoint_id,organization_id,integration_id,environment,attempt) SELECT 'whd_'||replace(gen_random_uuid()::text,'-',''),_id,id,_org,_integration,_environment,1 FROM public.webhook_endpoints WHERE organization_id=_org AND integration_id=_integration AND environment=_environment AND active AND deleted_at IS NULL AND (_endpoint IS NULL OR id=_endpoint) AND (_type='webhook.teste' OR ((_type=ANY(events) OR (split_part(_type,'.',1)||'.*')=ANY(events)) AND (company_id IS NULL OR company_id=_company))); GET DIAGNOSTICS n=ROW_COUNT; RETURN n; END $$;
REVOKE ALL ON FUNCTION public.emit_webhook_event(text,uuid,uuid,public.environment,text,text,uuid,uuid) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.emit_webhook_event(text,uuid,uuid,public.environment,text,text,uuid,uuid) TO service_role;
ALTER TABLE public.webhook_endpoints ADD CONSTRAINT webhook_endpoints_events_known CHECK (events <@ ARRAY['webhook.teste','nota.autorizada','nota.rejeitada','nota.cancelada','nota.cancelamento_em_analise','nota.cancelamento_indeferido','nota.substituida','nota.cancelada_prefeitura','nota.bloqueada_prefeitura','nota.manifestacao','empresa.situacao_alterada','certificado.vencendo','certificado.vencido','municipio.disponivel','nota.*','empresa.*','certificado.*','municipio.*']::text[]) NOT VALID;